'use client';

import * as React from 'react';
import { useState, useEffect, useCallback, useMemo, useRef, Fragment } from 'react';
import {
  type CommandDefinition,
  type CommandRegistryManager,
  type KeyBinding,
  type NavigateAdapter,
  type UseBackgroundTasks,
  kbd,
  matchKeyBinding,
  useCommandExecution,
  useCommandRegistry,
  useGlobalShortcuts,
  useMultiStepExecution
} from '@constructive-io/command-palette';
import {
  CommandDialog,
  CommandDialogPopup,
  CommandInput,
  CommandList,
  CommandGroup,
  CommandItem,
  CommandSeparator,
  CommandFooter,
  CommandPanel,
  CommandEmpty
} from '@/components/ui/command';
import { MultiStepView } from './multi-step/multi-step-view';
import { KbdShortcut } from './kbd-shortcut';
import { InlineTaskBar } from './background/inline-task-bar';

const ICON_PROPS = { className: 'size-4 shrink-0' } as const;

const emptyContent = (
  <div className="flex flex-col items-center gap-2 py-4">
    <p className="text-sm">No commands found</p>
    <p className="text-xs text-muted-foreground">Try a different search term</p>
  </div>
);

const footerContent = (
  <div className="flex items-center gap-4">
    <span className="flex items-center gap-1 text-xs">
      <kbd className="rounded-xs border bg-muted px-1">↑</kbd>
      <kbd className="rounded-xs border bg-muted px-1">↓</kbd>
      Navigate
    </span>
    <span className="flex items-center gap-1 text-xs">
      <kbd className="rounded-xs border bg-muted px-1">↵</kbd>
      Select
    </span>
    <span className="flex items-center gap-1 text-xs">
      <kbd className="rounded-xs border bg-muted px-1">esc</kbd>
      Close
    </span>
  </div>
);

export interface CommandPaletteProps {
  /** Registry instance holding commands and groups */
  registry: CommandRegistryManager;
  /** Navigation adapter for 'navigation' type commands */
  navigate?: NavigateAdapter;
  /** Controlled open state */
  open?: boolean;
  /** Callback when open state changes */
  onOpenChange?: (open: boolean) => void;
  /** Keyboard shortcut binding to toggle the palette (default: Cmd/Ctrl+K) */
  shortcut?: KeyBinding;
  /** Search input placeholder */
  placeholder?: string;
  /** Accessible label announced for the command dialog */
  label?: string;
  /** Background task tracker — enables `background: true` commands */
  backgroundTasks?: UseBackgroundTasks;
}

export function CommandPalette({
  registry,
  navigate,
  open: controlledOpen,
  onOpenChange,
  shortcut = kbd('k', 'mod'),
  placeholder = 'Type a command or search…',
  label = 'Command palette',
  backgroundTasks,
}: CommandPaletteProps) {
  const [internalOpen, setInternalOpen] = useState(false);
  const [search, setSearch] = useState('');
  const isControlled = controlledOpen !== undefined;
  const open = isControlled ? controlledOpen : internalOpen;

  const setOpen = useCallback(
    (next: boolean) => {
      if (!isControlled) {
        setInternalOpen(next);
      }
      onOpenChange?.(next);
      // Reset search when closing
      if (!next) {
        setSearch('');
      }
    },
    [isControlled, onOpenChange]
  );

  // Multi-step flow state
  const multiStep = useMultiStepExecution({
    onCompleted: () => {
      setOpen(false);
    },
  });

  const handleMultiStepStart = useCallback(
    (cmd: CommandDefinition) => {
      if (cmd.multiStep) {
        multiStep.start(cmd.id, cmd.multiStep);
      }
    },
    [multiStep.start]
  );

  const handleMultiStepCancel = useCallback(() => {
    multiStep.cancel();
    setSearch('');
    // Don't close palette — return to command list (layered escape)
  }, [multiStep.cancel]);

  // Global keyboard shortcut to toggle palette
  const openRef = useRef(open);
  openRef.current = open;

  useEffect(() => {
    function handleKeyDown(e: KeyboardEvent) {
      if (matchKeyBinding(e, shortcut)) {
        e.preventDefault();
        setOpen(!openRef.current);
      }
    }
    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [shortcut, setOpen]);

  const { commands, groups } = useCommandRegistry(registry);
  const { execute } = useCommandExecution(navigate, handleMultiStepStart, backgroundTasks);

  // Global command shortcuts (disabled when palette is open)
  useGlobalShortcuts(commands, execute, !open);

  // Build grouped items sorted by priority
  const groupedItems = useMemo(() => {
    return [...groups]
      .sort((a, b) => a.priority - b.priority)
      .map((group) => {
        const groupCommands = commands
          .filter((cmd) => cmd.group === group.id && !cmd.hidden)
          .sort((a, b) => (a.priority ?? 99) - (b.priority ?? 99));

        return { id: group.id, label: group.label, commands: groupCommands };
      })
      .filter((g) => g.commands.length > 0);
  }, [commands, groups]);

  const handleSelect = useCallback(
    async (cmd: CommandDefinition) => {
      if (cmd.disabled) return;

      // Background commands: fire-and-forget, configurable palette behavior
      if (cmd.background && backgroundTasks) {
        const behavior = cmd.backgroundBehavior ?? 'close';
        if (typeof behavior === 'function') {
          behavior({
            close: () => setOpen(false),
            reset: () => setSearch(''),
            setSearch,
          });
        } else {
          switch (behavior) {
            case 'close':
              setOpen(false);
              break;
            case 'reset':
              setSearch('');
              break;
            case 'persist':
              break;
          }
        }
        void execute(cmd);
        return;
      }

      // Non-background: multi-step stays open, everything else closes
      if (cmd.type !== 'multi-step') {
        setOpen(false);
      }
      await execute(cmd);
    },
    [execute, setOpen, backgroundTasks]
  );

  const isMultiStepActive =
    multiStep.state !== null && multiStep.config !== null;

  const hasTasks = backgroundTasks != null && backgroundTasks.tasks.length > 0;

  return (
    <CommandDialog
      className={hasTasks ? 'max-h-[500px]' : undefined}
      label={label}
      onOpenChange={(next) => {
        if (!next && isMultiStepActive) {
          handleMultiStepCancel();
          return;
        }
        setOpen(next);
      }}
      open={open}
    >
      <CommandDialogPopup>
        {isMultiStepActive ? (
          <MultiStepView
            config={multiStep.config!}
            state={multiStep.state!}
            onCompleteStep={multiStep.completeStep}
            onBack={multiStep.goBack}
            onSkip={multiStep.skipStep}
            onCancel={handleMultiStepCancel}
            onError={multiStep.setError}
          />
        ) : (
          <>
            <CommandInput
              value={search}
              onValueChange={setSearch}
              placeholder={placeholder}
            />
            <CommandPanel>
              <CommandList className={hasTasks ? 'max-h-56' : undefined}>
                <CommandEmpty>{emptyContent}</CommandEmpty>
                {groupedItems.map((group, i) => (
                  <Fragment key={group.id}>
                    <CommandGroup heading={group.label}>
                      {group.commands.map((cmd) => (
                        <CommandItem
                          key={cmd.id}
                          value={cmd.id}
                          keywords={cmd.keywords}
                          disabled={cmd.disabled}
                          onSelect={() => handleSelect(cmd)}
                        >
                          {cmd.icon &&
                            typeof cmd.icon !== 'string' &&
                            React.createElement(cmd.icon, ICON_PROPS)}
                          <div className="flex min-w-0 flex-col">
                            <span className="truncate">{cmd.label}</span>
                            {cmd.description && (
                              <span className="truncate text-xs text-muted-foreground">
                                {cmd.description}
                              </span>
                            )}
                          </div>
                          {cmd.shortcut && (
                            <span className="ml-auto pl-4">
                              <KbdShortcut binding={cmd.shortcut} />
                            </span>
                          )}
                        </CommandItem>
                      ))}
                    </CommandGroup>
                    {i < groupedItems.length - 1 && <CommandSeparator />}
                  </Fragment>
                ))}
              </CommandList>
            </CommandPanel>
            {backgroundTasks && backgroundTasks.tasks.length > 0 && (
              <InlineTaskBar
                tasks={backgroundTasks.tasks}
                onCancel={backgroundTasks.cancel}
                onDismiss={backgroundTasks.dismiss}
              />
            )}
            <CommandFooter>{footerContent}</CommandFooter>
          </>
        )}
      </CommandDialogPopup>
    </CommandDialog>
  );
}

import * as React from 'react';
import { formatKeyBinding, type KeyBinding } from '@constructive-io/command-palette';
import { cn } from '@/lib/utils';

export interface KbdShortcutProps {
  binding: KeyBinding;
  className?: string;
}

/**
 * Renders a KeyBinding as individual `<kbd>` elements (Raycast-style).
 *
 * Example: `⌘` `H` — each key is a separate styled box.
 */
export function KbdShortcut({ binding, className }: KbdShortcutProps) {
  const keys = formatKeyBinding(binding);

  return (
    <span className={cn('inline-flex items-center gap-0.5', className)}>
      {keys.map((k, i) => (
        <kbd
          key={i}
          className="inline-flex h-5 min-w-5 items-center justify-center rounded-xs border bg-muted px-1 text-[11px] font-medium text-muted-foreground"
        >
          {k}
        </kbd>
      ))}
    </span>
  );
}

'use client';

import * as React from 'react';
import { useCallback, useEffect } from 'react';
import { AnimatePresence, motion } from 'motion/react';
import {
  isEditableTarget,
  type MultiStepConfig,
  type MultiStepState
} from '@constructive-io/command-palette';
import { ArrowLeftIcon, LoaderCircleIcon } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Separator } from '@/components/ui/separator';
import { StepIndicator } from './step-indicator';

interface MultiStepViewProps {
  config: MultiStepConfig<any>;
  state: MultiStepState<any>;
  onCompleteStep: (output: Partial<any>) => void;
  onBack: () => void;
  onSkip: () => void;
  onCancel: () => void;
  onError: (error: Error | string) => void;
}

const SLIDE_OFFSET = 80;
const TRANSITION = { duration: 0.2, ease: 'easeInOut' as const };

const slideVariants = {
  enter: (dir: string) => ({
    x: dir === 'backward' ? -SLIDE_OFFSET : SLIDE_OFFSET,
    opacity: 0,
  }),
  center: { x: 0, opacity: 1 },
  exit: (dir: string) => ({
    x: dir === 'backward' ? SLIDE_OFFSET : -SLIDE_OFFSET,
    opacity: 0,
  }),
};

export function MultiStepView({
  config,
  state,
  onCompleteStep,
  onBack,
  onSkip,
  onCancel,
  onError,
}: MultiStepViewProps) {
  const { currentStepIndex, steps, direction, flowStatus } = state;
  const stepDef = config.steps[currentStepIndex];
  if (!stepDef) return null;

  const currentStep = steps[currentStepIndex];
  const totalSteps = config.steps.length;
  const isFirst = currentStepIndex === 0;
  const isLast = currentStepIndex === totalSteps - 1;
  const isCompleting = flowStatus === 'completing';

  const StepComponent = stepDef.Component;

  // Prevent cmdk Command root from intercepting keys during multi-step.
  // Enter/ArrowUp/ArrowDown are stopped so they reach step form inputs instead
  // of being swallowed by cmdk's item-select / navigation handlers.
  // Escape is NOT stopped — Radix Dialog needs it for layered dismiss.
  const handleKeyDown = useCallback((e: React.KeyboardEvent) => {
    if (e.key === 'Enter' || e.key === 'ArrowUp' || e.key === 'ArrowDown') {
      e.stopPropagation();
    }
  }, []);

  // Backspace keyboard navigation — go back when not in an editable target
  useEffect(() => {
    function handleKeyDown(e: KeyboardEvent) {
      if (e.key === 'Backspace' && !isFirst && !isEditableTarget(e.target)) {
        e.preventDefault();
        onBack();
      }
    }
    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [isFirst, onBack]);

  return (
    <div className="flex flex-col" onKeyDown={handleKeyDown}>
      <div className="flex items-center gap-2 px-3 py-2">
        <Button
          onClick={isFirst ? onCancel : onBack}
          aria-label={isFirst ? 'Back to commands' : 'Go back'}
          size="icon-xs"
          variant="ghost"
        >
          <ArrowLeftIcon />
        </Button>
        <span className="text-sm font-medium">
          Step {currentStepIndex + 1} of {totalSteps}: {stepDef.title}
        </span>
      </div>
      <Separator />

      {/* Step indicator */}
      <StepIndicator steps={steps} currentIndex={currentStepIndex} />

      {/* Step content with AnimatePresence */}
      <div className="relative min-h-[120px] overflow-hidden px-3 py-2">
        <AnimatePresence mode="wait" custom={direction}>
          <motion.div
            key={stepDef.id}
            custom={direction}
            variants={slideVariants}
            initial="enter"
            animate="center"
            exit="exit"
            transition={TRANSITION}
          >
            {isCompleting ? (
              <div className="flex items-center justify-center gap-2 py-8 text-sm text-muted-foreground">
                <LoaderCircleIcon aria-hidden="true" className="size-4 animate-spin" />
                Submitting…
              </div>
            ) : currentStep.status === 'loading' ? (
              <div className="flex items-center justify-center gap-2 py-8 text-sm text-muted-foreground">
                <LoaderCircleIcon aria-hidden="true" className="size-4 animate-spin" />
                Loading…
              </div>
            ) : (
              <StepComponent
                context={state.context as any}
                data={currentStep.data}
                onComplete={onCompleteStep}
                onBack={onBack}
                onSkip={onSkip}
                onError={onError}
                status={currentStep.status}
                error={currentStep.error}
                isFirst={isFirst}
                isLast={isLast}
                stepIndex={currentStepIndex}
                totalSteps={totalSteps}
              />
            )}
          </motion.div>
        </AnimatePresence>
      </div>

      <Separator />
      <div className="flex items-center justify-between px-3 py-2">
        <span className="flex items-center gap-1 text-xs">
          <kbd className="rounded-xs border bg-muted px-1">esc</kbd>
          Back to list
        </span>
        <div className="flex items-center gap-3">
          {!isFirst && (
            <span className="flex items-center gap-1 text-xs">
              <kbd className="rounded-xs border bg-muted px-1">⌫</kbd>
              Back
            </span>
          )}
          {stepDef.skippable && !isLast && (
            <Button onClick={onSkip} size="xs" variant="ghost">
              Skip
            </Button>
          )}
          <span className="flex items-center gap-1 text-xs">
            <kbd className="rounded-xs border bg-muted px-1">↵</kbd>
            {isLast ? 'Finish' : 'Continue'}
          </span>
        </div>
      </div>
    </div>
  );
}

'use client';

import * as React from 'react';
import type { StepState } from '@constructive-io/command-palette';
import { cn } from '@/lib/utils';

interface StepIndicatorProps {
  steps: StepState[];
  currentIndex: number;
}

export function StepIndicator({ steps, currentIndex }: StepIndicatorProps) {
  return (
    <div className="flex items-center justify-center gap-1.5 py-2">
      {steps.map((step, i) => (
        <React.Fragment key={i}>
          {i > 0 && (
            <div
              className={cn(
                'h-px w-4',
                step.status === 'complete' || steps[i - 1].status === 'complete'
                  ? 'bg-foreground'
                  : 'bg-border'
              )}
            />
          )}
          <div
            className={cn(
              'size-2 rounded-full transition-[background-color,box-shadow,border-color]',
              step.status === 'complete'
                ? 'bg-foreground'
                : step.status === 'error'
                  ? 'bg-destructive ring-2 ring-destructive/30'
                  : step.status === 'active' || step.status === 'loading'
                    ? 'bg-foreground ring-2 ring-foreground/30'
                    : 'border border-border bg-transparent'
            )}
            aria-label={`Step ${i + 1}: ${step.status}`}
            aria-current={i === currentIndex ? 'step' : undefined}
          />
        </React.Fragment>
      ))}
    </div>
  );
}

'use client';

import { AnimatePresence } from 'motion/react';
import { TaskCard } from './task-card';
import type { BackgroundTask } from '@constructive-io/command-palette';

const MAX_VISIBLE = 5;

export interface BackgroundTaskStackProps {
  tasks: BackgroundTask[];
  onCancel: (taskId: string) => void;
  onDismiss: (taskId: string) => void;
  /** Override default positioning */
  className?: string;
}

export function BackgroundTaskStack({
  tasks,
  onCancel,
  onDismiss,
  className,
}: BackgroundTaskStackProps) {
  if (tasks.length === 0) return null;

  const visible = tasks.slice(0, MAX_VISIBLE);
  const overflow = tasks.length - MAX_VISIBLE;

  return (
    <div
      className={
        className ??
        'fixed end-4 bottom-4 z-[var(--z-layer-toast)] flex flex-col-reverse items-end gap-2'
      }
    >
      {overflow > 0 && (
        <div className="rounded-sm border bg-popover px-3 py-1.5 text-xs text-muted-foreground shadow-sm">
          +{overflow} more task{overflow > 1 ? 's' : ''}
        </div>
      )}
      <AnimatePresence mode="popLayout">
        {visible.map((task) => (
          <TaskCard
            key={task.id}
            task={task}
            onCancel={onCancel}
            onDismiss={onDismiss}
          />
        ))}
      </AnimatePresence>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { AnimatePresence, motion } from 'motion/react';
import type { BackgroundTask } from '@constructive-io/command-palette';
import { ChevronDownIcon } from 'lucide-react';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { cn } from '@/lib/utils';
import { StatusIcon, ElapsedTime } from './task-icons';

export interface InlineTaskBarProps {
  tasks: BackgroundTask[];
  onCancel: (taskId: string) => void;
  onDismiss: (taskId: string) => void;
}

const MAX_INLINE = 3;

function InlineTaskRow({
  task,
  onCancel,
  onDismiss,
}: {
  task: BackgroundTask;
  onCancel: (id: string) => void;
  onDismiss: (id: string) => void;
}) {
  const [expanded, setExpanded] = useState(false);
  const isRunning = task.status === 'running';

  return (
    <motion.div
      layout
      initial={{ opacity: 0, height: 0 }}
      animate={{ opacity: 1, height: 'auto' }}
      exit={{ opacity: 0, height: 0 }}
      transition={{ type: 'spring', stiffness: 500, damping: 35 }}
      className="overflow-hidden"
    >
      <div className="flex items-center gap-1 px-1.5 py-1">
        <Button
          aria-expanded={expanded}
          className="min-w-0 flex-1 justify-start border-0 px-1.5"
          onClick={() => setExpanded((value) => !value)}
          size="xs"
          variant="ghost"
        >
          <StatusIcon status={task.status} />
          <span className="min-w-0 flex-1 truncate text-left">{task.label}</span>
          <span className="shrink-0 text-[10px] text-muted-foreground">
            <ElapsedTime startedAt={task.startedAt} completedAt={task.completedAt} />
          </span>
          <ChevronDownIcon
            className={cn('transition-transform', expanded && 'rotate-180')}
            data-icon="inline-end"
          />
        </Button>
        <Button
          aria-label={`${isRunning ? 'Cancel' : 'Dismiss'} ${task.label}`}
          onClick={() => (isRunning ? onCancel(task.id) : onDismiss(task.id))}
          size="xs"
          variant="ghost"
        >
          {isRunning ? 'Cancel' : 'Dismiss'}
        </Button>
      </div>

      {/* Expanded error / details */}
      <AnimatePresence>
        {expanded && (
          <motion.div
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: 'auto', opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            transition={{ duration: 0.15 }}
            className="overflow-hidden"
          >
            <div className="flex flex-col gap-0.5 px-3 pb-1.5 pl-8 text-[10px] text-muted-foreground">
              <div>
                Command: <span className="font-mono">{task.commandId}</span>
              </div>
              <div>Started: {new Date(task.startedAt).toLocaleTimeString()}</div>
              {task.completedAt && (
                <div>Completed: {new Date(task.completedAt).toLocaleTimeString()}</div>
              )}
              {task.error && (
                <div className="text-destructive">{task.error.message}</div>
              )}
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.div>
  );
}

export function InlineTaskBar({ tasks, onCancel, onDismiss }: InlineTaskBarProps) {
  if (tasks.length === 0) return null;

  const visible = tasks.slice(0, MAX_INLINE);
  const overflow = tasks.length - MAX_INLINE;

  const runningCount = tasks.filter((t) => t.status === 'running').length;
  const errorCount = tasks.filter((t) => t.status === 'error').length;

  return (
    <div className="relative -mx-px shrink-0 rounded-b-xl border border-t-0 bg-popover bg-clip-padding text-popover-foreground shadow-xs [clip-path:inset(0_1px)] dark:bg-clip-border" data-slot="inline-task-bar">
      {/* Summary header */}
      <div className="flex items-center gap-2 px-3 py-1.5">
        <span className="text-[10px] font-medium uppercase tracking-wider text-muted-foreground">
          Tasks
        </span>
        {runningCount > 0 && (
          <Badge size="sm" variant="info">
            <StatusIcon status="running" />
            {runningCount}
          </Badge>
        )}
        {errorCount > 0 && (
          <Badge size="sm" variant="error">
            {errorCount} failed
          </Badge>
        )}
        {tasks.length > 0 && (
          <span className="ml-auto text-[10px] text-muted-foreground">
            {tasks.length} total
          </span>
        )}
      </div>

      {/* Task rows */}
      <div className="max-h-32 overflow-y-auto">
        <AnimatePresence mode="popLayout">
          {visible.map((task) => (
            <InlineTaskRow
              key={task.id}
              task={task}
              onCancel={onCancel}
              onDismiss={onDismiss}
            />
          ))}
        </AnimatePresence>
      </div>

      {overflow > 0 && (
        <div className="px-3 py-1 text-[10px] text-muted-foreground">
          +{overflow} more task{overflow > 1 ? 's' : ''}
        </div>
      )}
    </div>
  );
}

'use client';

import { useState } from 'react';
import { motion } from 'motion/react';
import type { BackgroundTask } from '@constructive-io/command-palette';
import { cn } from '@/lib/utils';
import { Button } from '@/components/ui/button';
import { Separator } from '@/components/ui/separator';
import { StatusIcon, ElapsedTime } from './task-icons';

export interface TaskCardProps {
  task: BackgroundTask;
  onCancel: (taskId: string) => void;
  onDismiss: (taskId: string) => void;
}

const borderByStatus: Record<BackgroundTask['status'], string> = {
  running: 'border-info/30',
  success: 'border-success/30',
  error: 'border-destructive/30',
  cancelled: 'border-border'
};

export function TaskCard({ task, onCancel, onDismiss }: TaskCardProps) {
  const [expanded, setExpanded] = useState(false);
  const isRunning = task.status === 'running';

  return (
    <motion.div
      layout
      initial={{ opacity: 0, x: 80, scale: 0.95 }}
      animate={{ opacity: 1, x: 0, scale: 1 }}
      exit={{ opacity: 0, x: 80, scale: 0.95 }}
      transition={{ type: 'spring', stiffness: 500, damping: 30 }}
      className={cn(
        'w-72 rounded-sm border bg-popover text-popover-foreground shadow-sm',
        borderByStatus[task.status]
      )}
    >
      <div className="flex items-center gap-1 p-1.5">
        <Button
          aria-expanded={expanded}
          className="min-w-0 flex-1 justify-start border-0 px-1.5"
          onClick={() => setExpanded((value) => !value)}
          size="sm"
          variant="ghost"
        >
          <StatusIcon status={task.status} />
          <span className="min-w-0 flex-1 truncate text-left">{task.label}</span>
          <span className="shrink-0 text-xs text-muted-foreground">
            <ElapsedTime startedAt={task.startedAt} completedAt={task.completedAt} />
          </span>
        </Button>
        <Button
          aria-label={`${isRunning ? 'Cancel' : 'Dismiss'} ${task.label}`}
          onClick={() => (isRunning ? onCancel(task.id) : onDismiss(task.id))}
          size="xs"
          variant="ghost"
        >
          {isRunning ? 'Cancel' : 'Dismiss'}
        </Button>
      </div>

      {/* Expanded details */}
      {expanded && (
        <motion.div
          initial={{ height: 0, opacity: 0 }}
          animate={{ height: 'auto', opacity: 1 }}
          exit={{ height: 0, opacity: 0 }}
          className="overflow-hidden"
        >
          <Separator />
          <div className="flex flex-col gap-1 px-3 py-2 text-xs text-muted-foreground">
            <div>Command: {task.commandId}</div>
            <div>Started: {new Date(task.startedAt).toLocaleTimeString()}</div>
            {task.completedAt && (
              <div>
                Completed: {new Date(task.completedAt).toLocaleTimeString()}
              </div>
            )}
            {task.error && (
              <div className="text-destructive">{task.error.message}</div>
            )}
          </div>
        </motion.div>
      )}
    </motion.div>
  );
}

'use client';

import { useState, useEffect, useRef } from 'react';
import type { BackgroundTaskStatus } from '@constructive-io/command-palette';
import {
  BanIcon,
  CircleCheckIcon,
  CircleXIcon,
  LoaderCircleIcon,
  type LucideIcon
} from 'lucide-react';
import { cn } from '@/lib/utils';

const statusPresentation: Record<
  BackgroundTaskStatus,
  { icon: LucideIcon; className: string }
> = {
  running: { icon: LoaderCircleIcon, className: 'animate-spin text-info' },
  success: { icon: CircleCheckIcon, className: 'text-success' },
  error: { icon: CircleXIcon, className: 'text-destructive' },
  cancelled: { icon: BanIcon, className: 'text-muted-foreground' }
};

export function StatusIcon({
  status,
  className
}: {
  status: BackgroundTaskStatus;
  className?: string;
}) {
  const presentation = statusPresentation[status];
  const Icon = presentation.icon;
  return (
    <Icon
      aria-hidden="true"
      className={cn('size-3.5 shrink-0', presentation.className, className)}
    />
  );
}

export function ElapsedTime({ startedAt, completedAt }: { startedAt: number; completedAt: number | null }) {
  const [now, setNow] = useState(Date.now());
  const intervalRef = useRef<ReturnType<typeof setInterval>>(undefined);

  useEffect(() => {
    if (completedAt) return;
    intervalRef.current = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(intervalRef.current);
  }, [completedAt]);

  const elapsed = Math.round(((completedAt ?? now) - startedAt) / 1000);
  if (elapsed < 60) return <span className="tabular-nums">{elapsed}s</span>;
  const m = Math.floor(elapsed / 60);
  const s = elapsed % 60;
  return (
    <span className="tabular-nums">
      {m}m {s}s
    </span>
  );
}

